// ai-agents/orchestrator/src/fanout.ts (part of G3-25). Only the orchestrator starts runs.
import type { Client, Workflow } from "@temporalio/client";
import { defineSearchAttributeKey, SearchAttributeType, TypedSearchAttributes, WorkflowIdConflictPolicy } from "@temporalio/common";

const AGENT = defineSearchAttributeKey("Agent", SearchAttributeType.KEYWORD);

export const startRun = (client: Client, agent: string, thing: string, wf: string | Workflow, ...args: unknown[]) =>
  client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`, // nova:RH-1234 | cifix:fcp:<fingerprint> | upgrade:fcp:pr-<n> | bugfix:RH-1240
    taskQueue: `ai-agents-${agent}`, // one queue per agent: nobody starves anybody
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING, // a second trigger joins the open run
    typedSearchAttributes: new TypedSearchAttributes([{ key: AGENT, value: agent }]),
    args,
  });

// ~/temporal-lab/src/start2.ts: what a second start does
import { Client, Connection } from "@temporalio/client";
import { WorkflowIdConflictPolicy } from "@temporalio/common";
import { hello } from "./workflows.js";

const client = new Client({ connection: await Connection.connect({ address: "localhost:7233" }), namespace: "ai-agents" });
const opts = { taskQueue: "ai-agents-lab", workflowId: "lab:RH-5", args: ["Sean"] as [string] };
const join = { ...opts, workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING };
const a = await client.workflow.start(hello, join);
const b = await client.workflow.start(hello, join); // same ID, run still open
console.log("same run:", a.firstExecutionRunId === b.firstExecutionRunId);
try { await client.workflow.start(hello, opts); } // the default policy: FAIL
catch (e) { console.log("default policy:", (e as Error).constructor.name); }

// ai-agents/orchestrator/src/triggers/github-events.ts (part of G5-09): one routineRun per root cause
await temporal.workflow.signalWithStart(routineRun, {
  workflowId, // cifix:fcp:<fingerprint>: the root cause is the ID
  taskQueue: queueFor(routine), // ai-agents-cifix
  args: [{ routine }],
  signal: addTrigger, // sent to the open run, or to the run this call starts
  signalArgs: [Trigger.fromRun(run)],
  typedSearchAttributes: agentAttribute(routine), // Agent=cifix, as startRun sets it
  workflowIdReusePolicy: WorkflowIdReusePolicy.REJECT_DUPLICATE, // a closed root cause never starts again
}).catch(async (err: unknown) => {
  if (!(err instanceof WorkflowExecutionAlreadyStartedError)) throw err;
  await alerts.post(`${workflowId} came back after its run closed; a person should look (ping-pong?)`);
});

// ai-agents/orchestrator/src/main.ts (sketch): one worker per task queue
const QUEUES = ["nova", "cifix", "upgrade", "flaky", "bugfix", "health", "security", "orchestrator"];
const connection = await NativeConnection.connect({ address: config.temporalAddress });
const workers = await Promise.all(QUEUES.map((q) => Worker.create({
  connection, namespace: "ai-agents", taskQueue: `ai-agents-${q}`,
  workflowsPath: fileURLToPath(new URL("./workflows/index.js", import.meta.url)), activities,
})));
await Promise.all(workers.map((w) => w.run())); // each polls only its own queue
